const isHexDigit = (c) => (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c >= '0' && c <= '7'
const isLetter = (c) => (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
const isIdentPart = (c) => isLetter(c) || isDecDigit(c) || c === '_'

function tabStop(column) {
  return (Math.floor((column - 1) / 4) + 1) * 4 + 1
}

