  const entries = []
  let line = 1
  let column = 1
  for (const ch of source) {
    entries.push({ ch, line, column })
    if (ch === '\n') {
      line += 1
      column = 1
    } else if (ch === '\t') {
      column = tabStop(column)
    } else {
      column += 1
    }
  }
  for (let k = 0; k < 4; k += 1) entries.push({ ch: '', line, column })
  return entries
}

