  const arr = positions(source)
  const tokens = []
  let i = 0

  const at = (k) => arr[i + k]

  function fail(pos, reason) {
    throw new LexError(pos.line, pos.column, reason)
  }

  function textOf(start, end) {
    let s = ''
    for (let k = start; k < end; k += 1) s += arr[k].ch
    return s
