  function consumeDigitRun(pred) {
    let count = 0
    for (;;) {
      if (pred(at(0).ch)) {
        i += 1
        count += 1
      } else if (at(0).ch === '_' && count > 0 && pred(at(1).ch)) {
        i += 1
      } else {
        break
      }
    }
    return count
