        if (isDecDigit(at(j).ch)) {
          i += j
          consumeDigitRun(isDecDigit)
        }
      }
    }

    if (isIdentPart(at(0).ch)) {
      sweepTrailing()
      fail(pos, `invalid number ${textOf(start, i)}`)
    }

    tokens.push({ line: pos.line, column: pos.column, kind: 'number', body: textOf(start, i) })
  }

